        public static ShowcaseCardData GetCardById(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            _cardsById.TryGetValue(id, out var card);
            return card;
        }

        public static IReadOnlyList<ShowcaseCardData> GetCardsByCategory(string category)
        {
            if (string.IsNullOrEmpty(category) || category.Equals("all", StringComparison.OrdinalIgnoreCase))
                return Cards;
            return Cards.Where(c => c.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        public static ShowcaseReversoData GetReversoById(string id)
        {
            if (string.IsNullOrEmpty(id)) return Reversos[0];
            if (_reversosById.TryGetValue(id, out var rev)) return rev;
            return Reversos[0];
        }

        public static ShowcaseClanData GetClanById(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            _clansById.TryGetValue(id, out var clan);
            return clan;
        }

        public static ShowcaseCardData GetCardByDefinition(CardDefinition def)
        {
            if (def == null) return null;
            return GetCardByDefinitionIdOrName(def.Id, def.Name, def.Category.ToString());
        }

        public static ShowcaseCardData GetCardByDefinitionIdOrName(string defId, string name, string category = "")
        {
            if (string.IsNullOrEmpty(defId) && string.IsNullOrEmpty(name)) return null;

            if (!string.IsNullOrEmpty(defId) && _cardsById.TryGetValue(defId, out var byId))
            {
                return byId;
            }

            if (!string.IsNullOrEmpty(name))
            {
                var exact = Cards.FirstOrDefault(c => c.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
                if (exact != null) return exact;

                int parenIdx = name.IndexOf('(');
                string baseName = parenIdx > 0 ? name.Substring(0, parenIdx).Trim() : name.Trim();

                string targetCat = "";
                if (!string.IsNullOrEmpty(category))
                {
                    if (category.IndexOf("Champion", StringComparison.OrdinalIgnoreCase) >= 0) targetCat = "champions";
                    else if (category.IndexOf("Beast", StringComparison.OrdinalIgnoreCase) >= 0 || category.IndexOf("Kombat", StringComparison.OrdinalIgnoreCase) >= 0) targetCat = "kombat";
                    else if (category.IndexOf("Trompo", StringComparison.OrdinalIgnoreCase) >= 0) targetCat = "trompos";
                    else if (category.IndexOf("Arena", StringComparison.OrdinalIgnoreCase) >= 0) targetCat = "arenas";
                }

                var catList = !string.IsNullOrEmpty(targetCat) ? GetCardsByCategory(targetCat) : Cards;

                var baseMatch = catList.FirstOrDefault(c =>
                {
                    int cParen = c.Name.IndexOf('(');
                    string cBase = cParen > 0 ? c.Name.Substring(0, cParen).Trim() : c.Name.Trim();
                    return cBase.Equals(baseName, StringComparison.OrdinalIgnoreCase);
                });

                if (baseMatch != null) return baseMatch;

                // Match names ignoring punctuation/parentheses (e.g. "Diamante Leviatán" vs "Diamante (Leviatán)")
                string NormalizeClean(string s) => new string(s.Where(char.IsLetterOrDigit).ToArray()).ToLowerInvariant();
                string normTarget = NormalizeClean(name);
                var normMatch = catList.FirstOrDefault(c =>
                {
                    string cNorm = NormalizeClean(c.Name);
                    return cNorm.Equals(normTarget) || cNorm.Contains(normTarget) || normTarget.Contains(cNorm);
                });
                if (normMatch != null) return normMatch;

                var fuzzy = catList.FirstOrDefault(c => c.Name.IndexOf(baseName, StringComparison.OrdinalIgnoreCase) >= 0 || baseName.IndexOf(c.Name, StringComparison.OrdinalIgnoreCase) >= 0);
                if (fuzzy != null) return fuzzy;
            }

            return null;
        }
    }
